mapper.select:
SELECT
*
FROM change_log



        AND change_log.type = #{queryForm.type}



        AND ( INSTR(change_log.update_version,#{queryForm.keyword})
        OR INSTR(change_log.publish_author,#{queryForm.keyword})
        OR INSTR(change_log.content,#{queryForm.keyword})
        )



        AND DATE_FORMAT(change_log.public_date, '%Y-%m-%d') >= #{queryForm.publicDateBegin}


        AND DATE_FORMAT(change_log.public_date, '%Y-%m-%d') <= #{queryForm.publicDateEnd}



        AND DATE_FORMAT(change_log.create_time, '%Y-%m-%d') = #{queryForm.createTime}



        AND change_log.link = #{queryForm.link}


order by change_log.update_version desc
